import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long street(long[] money, int lo, int hi) {
        long take = 0, skip = 0;
        for (int i = lo; i < hi; i++) {
            long newTake = skip + money[i];
            skip = Math.max(skip, take);
            take = newTake;
        }
        return Math.max(take, skip);
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] money = new long[(int) n];
        for (int i = 0; i < money.length; i++) money[i] = Long.parseLong(next());

        if (n == 1) System.out.println(money[0]);
        else System.out.println(Math.max(street(money, 0, (int) n - 1), street(money, 1, (int) n)));
    }
}
